text:
{
  "questions": [
    {
      "question_id": "q1",
      "question": "Is there a reference method that can provide comparison values for tumor-boundary assessment?"
    },
    {
      "question_id": "q2",
      "question": "Do you already have numerical acceptance criteria, such as required accuracy or a detection limit?"
    },
    {
      "question_id": "q3",
      "question": "Over what range must the target variable for tumor-boundary assessment be followed?"
    },
    {
      "question_id": "q4",
      "question": "How quickly must a tumor-boundary assessment result be available?"
    },
    {
      "question_id": "q5",
      "question": "Where could the probe be installed for the proposed measurement?"
    },
    {
      "question_id": "q6",
      "question": "Would the proposed measurement point be hot, under pressure or prone to build-up?"
    }
  ],
  "plan": {
    "objective": "Assess research-stage feasibility for tumor-boundary discrimination on retained tissue samples.",
    "samples_and_states": [
      {
        "text": "Select retained tissue samples spanning the client-agreed target range and document their preparation and storage states.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "reference_measurements": [
      {
        "text": "Obtain matched comparison values using a reference method agreed with the client.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "setup": [
      {
        "text": "Acquire MIR, NIR and Raman spectra under documented conditions, recording Raman excitation separately from Raman shift.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "comparison": [
      {
        "text": "Compare each method with the reference assessments against client-agreed criteria set before testing, explicitly accounting for false-negative outcomes.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "validation": [
      {
        "text": "Test each fixed analysis on independent retained samples excluded from its development.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "go_no_go": [
      {
        "text": "Use the agreed criteria to decide whether further research is warranted, not whether to authorize surgical use.",
        "claim_type": "PROPOSAL",
        "evidence_ids": []
      }
    ],
    "not_demonstrated": [
      {
        "text": "Clinical performance of the proposed setup, including its false-negative behavior in vivo, remains unknown.",
        "claim_type": "UNKNOWN",
        "evidence_ids": []
      }
    ],
    "steps": [
      "Clarify requirements, reference method and acceptance criteria.",
      "Select representative retained tissue samples and document their states.",
      "Obtain matched reference assessments.",
      "Set up and compare MIR, NIR and Raman measurements.",
      "Validate on independent retained samples.",
      "Decide whether results justify further research under agreed criteria."
    ]
  },
  "decision_basis": [
    {
      "text": "Base research continuation on comparison with reference assessments on independent retained material against criteria agreed with the client before testing.",
      "claim_type": "PROPOSAL",
      "evidence_ids": []
    }
  ]
}
